use function Phit\{fit_lm, predict};

$fit = fit_lm('monthly_rent ~ area_m2 + bedrooms', $housing);
$fit['named'];  // ['(Intercept)' => ..., 'area_m2' => ..., 'bedrooms' => ...]

$p = predict($fit, ['area_m2' => [60, 90], 'bedrooms' => [1, 3]], interval: 'prediction');
$p['fit'];      // point predictions; $p['lower'], $p['upper'] give 95% intervals
